import voiceDurations from './voice-durations.json';

// Generated by promo/generate_voices.py — each provider introduces itself
// through gensay. Providers missing from the JSON (e.g. synthesis failed)
// are simply not scheduled.

export type VoiceCue = {
  id: string;
  file: string;
  from: number;
  durationInFrames: number;
};

const FPS = 30;
const framesOf = (s: number) => Math.round(s * FPS);
const byId = new Map(voiceDurations.map((v) => [v.id, v]));

// Absolute scene start frames — must match the Series in SizzleReel.tsx.
// Arc: boring built-in `say` → fancy cloud voices → (separately) local,
// free, SOTA open models on the warm daemon.
export const SCENES = {
  title: 0,
  say: 60,
  grid: 210,
  gemini: 480,
  daemon: 630,
  closing: 816,
} as const;

const buildCues = (): VoiceCue[] => {
  const cues: VoiceCue[] = [];
  // Schedules `id` at `from`; returns the frame after it ends.
  const add = (id: string, from: number): number => {
    const v = byId.get(id);
    if (!v) return from;
    const d = framesOf(v.seconds);
    cues.push({id, file: v.file, from, durationInFrames: d});
    return from + d;
  };

  // macOS speaks during the `say` demo scene.
  add('macos', SCENES.say + 30);

  // Cloud roll call across the providers grid, back to back.
  let f = SCENES.grid + 24;
  for (const id of ['elevenlabs', 'deepgram', 'openai', 'polly']) {
    f = add(id, f) + 5;
  }

  // Gemini speaks in its own feature scene.
  add('gemini', SCENES.gemini + 24);

  // Local AI voices speak during the warm-daemon scene.
  const after = add('chatterbox', SCENES.daemon + 24) + 5;
  add('vibevoice', after);

  return cues;
};

export const voiceCues = buildCues();

// Music duck factor at absolute frame f: 1 when nobody speaks,
// ~0.25 underneath any voice line, with short ramps.
export const duckFactor = (f: number): number => {
  let duck = 1;
  for (const c of voiceCues) {
    const end = c.from + c.durationInFrames;
    let v = 1;
    if (f >= c.from - 8 && f < c.from) {
      v = 1 - (0.75 * (f - (c.from - 8))) / 8;
    } else if (f >= c.from && f <= end) {
      v = 0.25;
    } else if (f > end && f <= end + 10) {
      v = 0.25 + (0.75 * (f - end)) / 10;
    }
    duck = Math.min(duck, v);
  }
  return duck;
};
